const body = $input.first().json.body || {};

// Valider l'entrée
const hasFile = !!(body.file_url || body.file_base64);
if (!hasFile) {
  return {
    json: {
      success: false,
      error: {
        code: 'INVALID_FORMAT',
        message: 'Missing file_url or file_base64'
      }
    }
  };
}

// Détecter le type de fichier
const fileType = body.file_type || (body.file_url?.split('.').pop()?.toLowerCase()) || 'unknown';
const action = body.action || 'translate';

// Pricing par défaut
const defaultPricing = {
  translate: { base: 5, per_1k_tokens: 1.0, per_page: 2, ocr_bonus: 3, max: 50 },
  summarize: { base: 3, per_1k_tokens: 0.5, per_page: 1, ocr_bonus: 3, max: 30 }
};
const pricing = body.plugin_context?.pricing?.[action] || defaultPricing[action] || defaultPricing.translate;

// OCR thresholds configurables (Phase 2.2)
const defaultOcrThresholds = {
  min_confidence: 0.7,
  hebrew_min_confidence: 0.6,
  aramaic_min_confidence: 0.5,
  retry_on_low_confidence: true
};
const ocrThresholds = body.plugin_context?.ocr_thresholds || defaultOcrThresholds;

// Déterminer si OCR est requis
const imageTypes = ['png', 'jpg', 'jpeg', 'webp', 'gif', 'bmp', 'tiff'];
const isImage = imageTypes.includes(fileType?.toLowerCase());
const ocrRequired = isImage || fileType === 'pdf';

// Détecter langue potentielle pour ajuster seuils OCR
const detectedLanguage = body.params?.source_language || body.plugin_context?.detected_language || 'unknown';
const isHebrewContent = detectedLanguage === 'hebrew' || detectedLanguage === 'he';
const isAramaicContent = detectedLanguage === 'aramaic' || detectedLanguage === 'arc';

// Ajuster le seuil de confiance selon la langue
let minConfidenceThreshold = ocrThresholds.min_confidence;
if (isHebrewContent) {
  minConfidenceThreshold = ocrThresholds.hebrew_min_confidence;
} else if (isAramaicContent) {
  minConfidenceThreshold = ocrThresholds.aramaic_min_confidence;
}

// Estimation selon le type
let estimatedPages, estimatedTokens, ocrConfidencePreview;

if (isImage) {
  estimatedPages = 1;
  estimatedTokens = 500;
  ocrConfidencePreview = isHebrewContent ? 0.75 : (isAramaicContent ? 0.65 : 0.85);
} else if (fileType === 'pdf') {
  estimatedPages = 5;
  estimatedTokens = 2500;
  ocrConfidencePreview = isHebrewContent ? 0.80 : (isAramaicContent ? 0.70 : 0.90);
} else {
  estimatedPages = 3;
  estimatedTokens = 1500;
  ocrConfidencePreview = 1.0;
}

// Calcul des crédits: base + (tokens/1000 * rate) + (pages * page_rate) + ocr_bonus
const base = pricing.base || 5;
const tokenCost = (estimatedTokens / 1000) * (pricing.per_1k_tokens || 1.0);
const pageCost = estimatedPages * (pricing.per_page || 2);
const ocrCost = ocrRequired ? (pricing.ocr_bonus || 3) : 0;

const total = base + tokenCost + pageCost + ocrCost;
const maxCredits = pricing.max || 50;
const estimatedCredits = Math.min(Math.ceil(total), maxCredits);

// Marge de sécurité de 10%
const tokensWithMargin = Math.ceil(estimatedTokens * 1.1);

// Warnings
const warnings = [];
if (ocrConfidencePreview < minConfidenceThreshold) {
  warnings.push(`OCR confidence (${ocrConfidencePreview}) below threshold (${minConfidenceThreshold})`);
}
if (ocrConfidencePreview < 0.8) {
  warnings.push('OCR confidence may vary on full document');
}
if (estimatedPages > 10) {
  warnings.push('Document exceeds recommended 10 pages limit');
}
if (isHebrewContent || isAramaicContent) {
  warnings.push(`${isHebrewContent ? 'Hebrew' : 'Aramaic'} content detected - using specialized OCR thresholds`);
}

return {
  json: {
    success: true,
    estimation: {
      tokens: tokensWithMargin,
      pages: estimatedPages,
      ocr_required: ocrRequired,
      ocr_confidence_preview: ocrConfidencePreview,
      detected_language: detectedLanguage
    },
    credits: {
      estimated: estimatedCredits,
      breakdown: {
        base: base,
        tokens: Math.round(tokenCost * 100) / 100,
        pages: pageCost,
        ocr: ocrCost
      },
      max_possible: maxCredits
    },
    ocr_thresholds: {
      applied: minConfidenceThreshold,
      config: ocrThresholds
    },
    warnings: warnings
  }
};

